{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2174-04-13 20:45:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Patel. I understand you've been having abdominal pain, nausea, and vomiting again. Can you tell me more about what’s been going on?"
    },
    {
      "turn_number": 2,
      "time": "2174-04-13 20:46:30",
      "speaker": "Patient",
      "text": "Yes, it started a few days ago. I just got back from vacation and I think I overdid it. The pain is right here in the middle, above my belly button. It feels like the last time I had that ulcer issue."
    },
    {
      "turn_number": 3,
      "time": "2174-04-13 20:47:45",
      "speaker": "Doctor",
      "text": "I see. And have you been able to keep your tube feeds going?"
    },
    {
      "turn_number": 4,
      "time": "2174-04-13 20:48:10",
      "speaker": "Patient",
      "text": "I’ve been trying, but I’ve been so nauseous. I’ve slowed them down a bit. I haven’t vomited through the tube, but I feel really full and uncomfortable."
    },
    {
      "turn_number": 5,
      "time": "2174-04-13 20:49:00",
      "speaker": "Doctor",
      "text": "Okay, that makes sense. Given your history with the GJ ulcer and recent symptoms, we’re going to keep you NPO—nothing by mouth—for now and give you IV fluids to stay hydrated."
    },
    {
      "turn_number": 6,
      "time": "2174-04-13 20:50:15",
      "speaker": "Patient",
      "text": "So no tube feeds at all?"
    },
    {
      "turn_number": 7,
      "time": "2174-04-13 20:51:00",
      "speaker": "Doctor",
      "text": "We’ll pause the tube feeds for tonight. We want to let your stomach rest. We’ll continue your medications through the G-tube as needed, but the nutrition will come through the IV for now."
    },
    {
      "turn_number": 8,
      "time": "2174-04-13 20:52:10",
      "speaker": "Patient",
      "text": "Okay, that’s fine. I just don’t want another ulcer."
    },
    {
      "turn_number": 9,
      "time": "2174-04-13 20:53:00",
      "speaker": "Doctor",
      "text": "We’re giving you an IV proton-pump inhibitor—lansoprazole—to help protect your stomach lining, just like before. And we’ll monitor your symptoms closely."
    },
    {
      "turn_number": 10,
      "time": "2174-04-13 20:54:15",
      "speaker": "Patient",
      "text": "Good. I’ve been on that at home. Is it the same dose?"
    },
    {
      "turn_number": 11,
      "time": "2174-04-13 20:55:00",
      "speaker": "Doctor",
      "text": "Yes, same dose—30 mg twice a day, but now it’s IV so it works faster. We also gave you some ondansetron for nausea and morphine for pain."
    },
    {
      "turn_number": 12,
      "time": "2174-04-13 20:56:20",
      "speaker": "Patient",
      "text": "The morphine helped a little, but I didn’t want too much. I get sleepy."
    },
    {
      "turn_number": 13,
      "time": "2174-04-13 20:57:30",
      "speaker": "Doctor",
      "text": "That’s okay—we’ll use it only as needed. Your labs came back normal—white count is fine, liver enzymes are okay, lipase is normal—so no signs of infection or pancreatitis."
    },
    {
      "turn_number": 14,
      "time": "2174-04-13 20:58:45",
      "speaker": "Patient",
      "text": "That’s a relief. I was worried about my liver too, since I’ve had fatty liver in the past."
    },
    {
      "turn_number": 15,
      "time": "2174-04-13 21:00:00",
      "speaker": "Doctor",
      "text": "Your ALT and AST are normal, and bilirubin is fine. Alkaline phosphatase is a bit high, but not concerning. We’ll keep an eye on it."
    },
    {
      "turn_number": 16,
      "time": "2174-04-14 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. How are you feeling today?"
    },
    {
      "turn_number": 17,
      "time": "2174-04-14 08:16:30",
      "speaker": "Patient",
      "text": "Better, actually. The pain is less intense. I haven’t needed any pain meds since last night."
    },
    {
      "turn_number": 18,
      "time": "2174-04-14 08:18:00",
      "speaker": "Doctor",
      "text": "That’s great. We’re going to restart your tube feeds today, but at a slower rate—50 cc/hr instead of 60. We’ll see how you tolerate it."
    },
    {
      "turn_number": 19,
      "time": "2174-04-14 08:19:30",
      "speaker": "Patient",
      "text": "Okay. Should I adjust anything at home after this?"
    },
    {
      "turn_number": 20,
      "time": "2174-04-14 08:21:00",
      "speaker": "Doctor",
      "text": "We’ll keep you on the same meds—rifaximin for bacterial overgrowth, lansoprazole, and your antidepressants. No changes there."
    },
    {
      "turn_number": 21,
      "time": "2174-04-14 08:22:30",
      "speaker": "Patient",
      "text": "And the iron? My ferritin was low last time."
    },
    {
      "turn_number": 22,
      "time": "2174-04-14 08:23:45",
      "speaker": "Doctor",
      "text": "Yes, your ferritin is still low at 13, so we’re keeping you on ferrous sulfate. We’ll check it again at your follow-up."
    },
    {
      "turn_number": 23,
      "time": "2174-04-14 08:25:00",
      "speaker": "Patient",
      "text": "Okay, good. I’ve been taking it with vitamin C to help absorption."
    },
    {
      "turn_number": 24,
      "time": "2174-04-14 08:26:15",
      "speaker": "Doctor",
      "text": "That’s smart. You’re doing everything right. Let’s focus on getting your feeds back up slowly."
    },
    {
      "turn_number": 25,
      "time": "2174-04-15 09:00:00",
      "speaker": "Doctor",
      "text": "Morning. How’s the feeding going?"
    },
    {
      "turn_number": 26,
      "time": "2174-04-15 09:01:20",
      "speaker": "Patient",
      "text": "So far so good. No nausea, no pain. I’m actually feeling stronger."
    },
    {
      "turn_number": 27,
      "time": "2174-04-15 09:02:45",
      "speaker": "Doctor",
      "text": "Excellent. We’ll keep the feeds at 50 cc/hr for now. Your physical exam is normal—soft belly, no tenderness. That’s a good sign."
    },
    {
      "turn_number": 28,
      "time": "2174-04-15 09:04:00",
      "speaker": "Patient",
      "text": "Do we know if it was another ulcer or just irritation?"
    },
    {
      "turn_number": 29,
      "time": "2174-04-15 09:05:30",
      "speaker": "Doctor",
      "text": "We don’t have an endoscopy this time, but given your response to the PPI and symptom improvement, it’s likely irritation or early ulcer healing. We’ll follow up with GI soon."
    },
    {
      "turn_number": 30,
      "time": "2174-04-15 09:07:00",
      "speaker": "Patient",
      "text": "Okay, I’ll make sure to keep that appointment."
    },
    {
      "turn_number": 31,
      "time": "2174-04-16 10:30:00",
      "speaker": "Doctor",
      "text": "Hi again. Your team just documented the nutrition adjustment—feeds are continuing at 50 cc/hr. You’re doing well."
    },
    {
      "turn_number": 32,
      "time": "2174-04-16 10:31:30",
      "speaker": "Patient",
      "text": "Thanks. I feel like I’m back to my baseline. Can I go home soon?"
    },
    {
      "turn_number": 33,
      "time": "2174-04-16 10:33:00",
      "speaker": "Doctor",
      "text": "Possibly tomorrow. We want to make sure you stay stable through the night. We’ll plan to discharge you if you continue improving."
    },
    {
      "turn_number": 34,
      "time": "2174-04-16 10:34:30",
      "speaker": "Patient",
      "text": "That would be great. I miss my routine."
    },
    {
      "turn_number": 35,
      "time": "2174-04-16 15:00:00",
      "speaker": "Doctor",
      "text": "Just checking in. Any pain or nausea since this morning?"
    },
    {
      "turn_number": 36,
      "time": "2174-04-16 15:01:15",
      "speaker": "Patient",
      "text": "None at all. I even walked down the hall twice today."
    },
    {
      "turn_number": 37,
      "time": "2174-04-16 15:02:30",
      "speaker": "Doctor",
      "text": "That’s fantastic. You’re clearly ready to transition home."
    },
    {
      "turn_number": 38,
      "time": "2174-04-17 08:00:00",
      "speaker": "Doctor",
      "text": "Good news—we’re discharging you today. You’ve had four days of monitoring, and your symptoms have significantly improved."
    },
    {
      "turn_number": 39,
      "time": "2174-04-17 08:01:30",
      "speaker": "Patient",
      "text": "That’s wonderful. What do I need to do at home?"
    },
    {
      "turn_number": 40,
      "time": "2174-04-17 08:03:00",
      "speaker": "Doctor",
      "text": "Continue tube feeds at 50 cc/hr continuously. No oral intake. Keep taking all your medications, including lansoprazole and rifaximin."
    },
    {
      "turn_number": 41,
      "time": "2174-04-17 08:04:30",
      "speaker": "Patient",
      "text": "What about pain? I might need something if it flares up."
    },
    {
      "turn_number": 42,
      "time": "2174-04-17 08:06:00",
      "speaker": "Doctor",
      "text": "We’re prescribing oxycodone 5 mg every 4 hours as needed for pain. But use it sparingly—it can cause drowsiness and constipation."
    },
    {
      "turn_number": 43,
      "time": "2174-04-17 08:07:30",
      "speaker": "Patient",
      "text": "I understand. I’ll stick to the ondansetron if I feel nauseous."
    },
    {
      "turn_number": 44,
      "time": "2174-04-17 08:09:00",
      "speaker": "Doctor",
      "text": "Exactly. And call us or go to the ER if you develop a fever over 101.5, severe pain, vomiting, or redness around your tube site."
    },
    {
      "turn_number": 45,
      "time": "2174-04-17 08:10:30",
      "speaker": "Patient",
      "text": "Got it. And follow-up with surgery and GI?"
    },
    {
      "turn_number": 46,
      "time": "2174-04-17 08:12:00",
      "speaker": "Doctor",
      "text": "Yes, your surgeon will contact you. Also, continue moderate activity—no heavy lifting, but walking is encouraged."
    },
    {
      "turn_number": 47,
      "time": "2174-04-17 08:13:30",
      "speaker": "Patient",
      "text": "I’ve been doing that. I feel strong enough."
    },
    {
      "turn_number": 48,
      "time": "2174-04-17 08:15:00",
      "speaker": "Doctor",
      "text": "You’ve made great progress. We’re discharging you home in stable condition. Nurse will go over your meds and feeds before you leave."
    },
    {
      "turn_number": 49,
      "time": "2174-04-17 08:16:30",
      "speaker": "Patient",
      "text": "Thank you so much. I really appreciate the care."
    },
    {
      "turn_number": 50,
      "time": "2174-04-17 08:18:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and we’ll see you soon in clinic."
    },
    {
      "turn_number": 51,
      "time": "2174-04-17 10:00:00",
      "speaker": "Doctor",
      "text": "Just a quick update—your discharge paperwork is ready. You can leave once the nurse confirms your feeds are set up."
    },
    {
      "turn_number": 52,
      "time": "2174-04-17 10:01:30",
      "speaker": "Patient",
      "text": "Perfect. I’ve packed everything."
    },
    {
      "turn_number": 53,
      "time": "2174-04-17 11:30:00",
      "speaker": "Doctor",
      "text": "Nurse says you’re all set. Remember—no driving while on oxycodone."
    },
    {
      "turn_number": 54,
      "time": "2174-04-17 11:31:45",
      "speaker": "Patient",
      "text": "I won’t. My husband is picking me up."
    },
    {
      "turn_number": 55,
      "time": "2174-04-17 11:33:00",
      "speaker": "Doctor",
      "text": "Great. Stay hydrated, keep the feeds going, and rest."
    },
    {
      "turn_number": 56,
      "time": "2174-04-17 11:34:30",
      "speaker": "Patient",
      "text": "I will. Thanks again for everything."
    },
    {
      "turn_number": 57,
      "time": "2174-04-17 11:36:00",
      "speaker": "Doctor",
      "text": "You’re doing really well. We’re glad to see you improving."
    },
    {
      "turn_number": 58,
      "time": "2174-04-17 12:00:00",
      "speaker": "Doctor",
      "text": "One last thing—your ferritin and lipids are still being monitored. Keep taking your multivitamins and atorvastatin."
    },
    {
      "turn_number": 59,
      "time": "2174-04-17 12:01:30",
      "speaker": "Patient",
      "text": "I haven’t missed a dose. I know how important they are after bypass."
    },
    {
      "turn_number": 60,
      "time": "2174-04-17 12:03:00",
      "speaker": "Doctor",
      "text": "That’s exactly right. You’re managing your health very well."
    },
    {
      "turn_number": 61,
      "time": "2174-04-17 12:30:00",
      "speaker": "Doctor",
      "text": "Just checking—any last questions before discharge?"
    },
    {
      "turn_number": 62,
      "time": "2174-04-17 12:31:30",
      "speaker": "Patient",
      "text": "No, I think I’ve got it all. Feeds, meds, warning signs, follow-up. I’m ready."
    },
    {
      "turn_number": 63,
      "time": "2174-04-17 12:33:00",
      "speaker": "Doctor",
      "text": "Perfect. We’ll see you in the clinic soon. Take care."
    },
    {
      "turn_number": 64,
      "time": "2174-04-17 13:00:00",
      "speaker": "Doctor",
      "text": "Discharge is official. You’re cleared to go home now."
    },
    {
      "turn_number": 65,
      "time": "2174-04-17 13:01:30",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I’m so glad to be going home."
    },
    {
      "turn_number": 66,
      "time": "2174-04-17 13:03:00",
      "speaker": "Doctor",
      "text": "We’re glad too. Stay well, and call if anything changes."
    },
    {
      "turn_number": 67,
      "time": "2174-04-17 13:04:30",
      "speaker": "Patient",
      "text": "I will. Have a great day."
    }
  ],
  "summary": {
    "admission_start": "2174-04-13 20:32:00",
    "admission_end": "2174-04-17 14:45:00",
    "summary_paragraph": "The patient was admitted directly from clinic with recurrent epigastric pain, nausea, and vomiting, one month after a prior hospitalization for similar symptoms. With a history of Roux-en-Y gastric bypass and gastrostomy tube placement due to a previous GJ anastomotic ulcer, she was kept NPO, given IV fluids, IV proton-pump inhibitor, and IV morphine for pain. Tube feeds were restarted at a reduced rate and gradually tolerated. Her symptoms improved significantly over four days, with no signs of infection or organ dysfunction on labs. She was discharged home in stable condition on continuous tube feeds at 50 cc/hr, with instructions to continue home medications, use oxycodone for breakthrough pain, and follow up with surgery and GI. No procedures were performed during this admission.",
    "problems": [
      "Unspecified abdominal pain",
      "Fatty (change of) liver, not elsewhere classified",
      "Bariatric surgery status",
      "Major depressive disorder, single episode, unspecified",
      "Anxiety disorder, unspecified",
      "Polycystic ovarian syndrome",
      "Gastrostomy status",
      "Anemia, unspecified",
      "Hyperlipidemia, unspecified",
      "Unspecified mood [affective] disorder"
    ]
  }
}
